// Fixed acceptance test of the real series (C1). The executor must make it pass by writing src/clamp.mjs;
// it must not edit this file (the review is told so, and a changed test would change the tree the lead sees).
import assert from "node:assert/strict";
import { test } from "node:test";

test("clamp keeps a value inside [lo, hi]", async () => {
  const { clamp } = await import("../src/clamp.mjs");
  assert.equal(clamp(5, 0, 10), 5);
  assert.equal(clamp(-3, 0, 10), 0);
  assert.equal(clamp(42, 0, 10), 10);
  assert.equal(clamp(0, 0, 0), 0);
});

test("clamp rejects an empty range", async () => {
  const { clamp } = await import("../src/clamp.mjs");
  assert.throws(() => clamp(1, 5, 2), RangeError);
});

export function clamp(x, lo, hi) {
  if (lo > hi) throw new RangeError(`clamp: lo (${lo}) > hi (${hi})`);
  return Math.min(Math.max(x, lo), hi);
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { clamp } from "../src/clamp.mjs";

test("clamp returns x inside the range", () => {
  assert.equal(clamp(3, 1, 5), 3);
  assert.equal(clamp(1, 1, 5), 1);
  assert.equal(clamp(5, 1, 5), 5);
});

test("clamp limits values below and above the range", () => {
  assert.equal(clamp(-10, 1, 5), 1);
  assert.equal(clamp(10, 1, 5), 5);
});

test("clamp with equal bounds returns the bound", () => {
  assert.equal(clamp(7, 2, 2), 2);
  assert.equal(clamp(-7, 2, 2), 2);
});

test("clamp throws RangeError for reversed bounds", () => {
  assert.throws(() => clamp(0, 5, 1), RangeError);
});
